 async function createRoom(){if(!supabase)return;if(privateRoom&&roomPassword.length<4){notify('كلمة السر خاصها تكون 4 حروف على الأقل.');return;}setBusy(true);const {data,error}=await supabase.rpc('create_room',{p_name:roomName,p_private:privateRoom,p_max_players:maxPlayers,p_game_key:selectedGame,p_password:privateRoom?roomPassword:null});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(!r){notify('ما قدرناش نصايبو الغرفة.');return;}setRoomDialog(null);setCode(r.room_code);setRoomPassword('');await openRoom({id:r.room_id,code:r.room_code,name:roomName,is_private:privateRoom,max_players:maxPlayers,status:'open',game_key:selectedGame});}
 async function joinRoom(c:string){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('join_room',{p_code:c.trim().toUpperCase(),p_password:joinPassword||null});setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];if(r){setRoomDialog(null);setJoinPassword('');const found=rooms.find(x=>x.code===r.room_code);await openRoom({id:r.room_id,code:r.room_code,name:r.room_name,is_private:found?.is_private||false,max_players:found?.max_players||16,status:'open',game_key:found?.game_key});}}
