 async function loadRoomData(id:string){if(!supabase)return;const snapshot=await fetchRoomSnapshot(supabase,id);if(snapshot.memberError)notify(prettyError(snapshot.memberError));else setRoster(snapshot.members.map(member=>({...member,profile:snapshot.profiles.find(profile=>profile.id===member.user_id)})));if(snapshot.chatError)notify(prettyError(snapshot.chatError));else setMessages(snapshot.chat);const latest=snapshot.sessions[0];if(latest){await loadGame(latest);setTab(latest.status==='active'?'game':'room');}else{setGame(null);setGamePlayers([]);setGameResult(null);setTab('room');}} async function sendMessage(e:FormEvent){e.preventDefault();if(!supabase||!room||!chatText.trim())return;const body=chatText.trim();setChatText('');const {data,error}=await supabase.rpc('send_room_message',{p_room_id:room.id,p_body:body});if(error){notify(prettyError(error));setChatText(body);return;}const {data:row}=await supabase.from('chat_messages').select('id,user_id,body,created_at').eq('id',data).single();if(row)setMessages(prev=>[...prev,row]);}
 async function claimDaily(){if(!supabase)return;setBusy(true);const {data,error}=await supabase.rpc('claim_daily_reward');setBusy(false);if(error){notify(prettyError(error));return;}const r=data?.[0];notify('ربحتي '+r.coins_awarded+' عملة و '+(r.streak%3===0?5:2)+' جواهر و '+r.xp_awarded+' XP! سلسلة '+r.streak+' أيام.');await Promise.all([loadProfile(),loadDailyMissions()]);}
