 function startPractice(mode:'xo'|'connect4'|'rps'){
  setPracticeGame(mode);setPracticeXo(Array(9).fill(null));setPracticeConnect(Array(42).fill(0));setPracticeTurn('X');setPracticeRps('');setPracticeMessage(mode==='xo'?'نتا X. Bot هو O.':mode==='connect4'?'نتا الأحمر. Bot هو الأصفر.':'اختار حجر أو ورقة أو مقص.');
 }
 function practiceWinner(board:(string|null)[]){
  const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
  for(const line of lines){const [a,b,d]=line;if(board[a]&&board[a]===board[b]&&board[a]===board[d])return board[a];}
  return board.every(Boolean)?'draw':null;
 }
 function playPracticeXo(index:number){
  if(practiceGame!=='xo'||practiceXo[index]||practiceTurn!=='X'||practiceWinner(practiceXo))return;
  const next=[...practiceXo];next[index]='X';const w=practiceWinner(next);
  if(w){setPracticeXo(next);setPracticeMessage(w==='X'?'ربحتي الجولة!':'تعادل. جرب مرة أخرى.');return;}
  const empty=next.map((v,i)=>v? -1:i).filter(i=>i>=0);
  const botMove=(mark:string,board:(string|null)[])=>{for(const i of empty){const b=[...board];b[i]=mark;if(practiceWinner(b)===mark)return i;}return -1;};
  let bi=botMove('O',next);if(bi<0)bi=botMove('X',next);
  if(bi<0)bi=empty[Math.floor(Math.random()*empty.length)];
  if(bi!==undefined&&bi>=0)next[bi]='O';
  const result=practiceWinner(next);setPracticeXo(next);setPracticeMessage(result==='O'?'Bot ربح هاد الجولة.':result==='draw'?'تعادل.':'دورك دابا.');
 }
 function playPracticeConnect(col:number){
  if(practiceGame!=='connect4'||practiceMessage.startsWith('ربح')||practiceMessage.startsWith('Bot ربح')||practiceMessage==='تعادل.')return;
  const drop=(board:number[],column:number,mark:number)=>{const b=[...board];for(let row=5;row>=0;row--){const i=row*7+column;if(!b[i]){b[i]=mark;return b;}}return null;};
  const winner=(b:number[])=>{for(let r=0;r<6;r++)for(let x=0;x<7;x++){const v=b[r*7+x];if(!v)continue;for(const [dr,dc] of [[0,1],[1,0],[1,1],[1,-1]]){let ok=true;for(let k=1;k<4;k++){const rr=r+dr*k,cc=x+dc*k;if(rr<0||rr>=6||cc<0||cc>=7||b[rr*7+cc]!==v){ok=false;break;}}if(ok)return v;}}return b.every(Boolean)?3:0;};
  const first=drop(practiceConnect,col,1);if(!first){setPracticeMessage('هاد العمود عامر. اختار واحد آخر.');return;}
  let w=winner(first);if(w){setPracticeConnect(first);setPracticeMessage(w===1?'ربحتي على Bot!':'تعادل.');return;}
  let move=-1;for(let x=0;x<7;x++){const b=drop(first,x,2);if(b&&winner(b)===2){move=x;break;}}
  if(move<0)for(let x=0;x<7;x++){const b=drop(first,x,1);if(b&&winner(b)===1){move=x;break;}}
  if(move<0){const choices=[3,2,4,1,5,0,6].filter(x=>first[x]===0);move=choices[0]??-1;}
  const final=move>=0?drop(first,move,2):first;w=winner(final||first);setPracticeConnect(final||first);setPracticeMessage(w===1?'ربحتي على Bot!':w===2?'Bot ربح هاد الجولة.':w===3?'تعادل.':'دورك. اختار عموداً.');
 }
 function playPracticeRps(choice:string){
  const bot=['rock','paper','scissors'][Math.floor(Math.random()*3)];
  const names:any={rock:'حجر',paper:'ورقة',scissors:'مقص'};
  const result=choice===bot?'تعادل':(choice==='rock'&&bot==='scissors')||(choice==='paper'&&bot==='rock')||(choice==='scissors'&&bot==='paper')?'ربحتي الجولة!':'Bot ربح الجولة.';
  setPracticeRps('اختيارك: '+names[choice]+' · اختيار Bot: '+names[bot]);setPracticeMessage(result);
 }
 async function startGame(){if(!supabase||!room)return;setGameResult(null);setBusy(true);const {data,error}=await supabase.rpc('start_party_game',{p_room_id:room.id,p_game_key:selectedGame});setBusy(false);if(error){notify(prettyError(error));return;}await loadGame({id:data,game_key:selectedGame,status:'active',created_by:userId!});setTab('game');}
 async function loadGame(g:Game){if(!supabase)return;setGame(g);setGameResult(g.result||null);const [{data:players,error},{data:secret},{data:actions}]=await Promise.all([supabase.from('game_players').select('user_id,score').eq('session_id',g.id).order('score',{ascending:false}),supabase.rpc('get_my_game_secret',{p_session_id:g.id}),supabase.from('game_actions').select('user_id,action_key').eq('session_id',g.id)]);if(error)notify(prettyError(error));setGamePlayers((players||[]) as Player[]);setGameSecret(secret||{});setGameAction((actions||[]).some(a=>a.user_id===userId)?'sent':'');}
 async function submitAction(action:string,payload:any){if(!supabase||!game)return;setBusy(true);const {error}=await supabase.rpc('submit_party_action',{p_session_id:game.id,p_action_key:action,p_payload:payload});setBusy(false);if(error)notify(prettyError(error));else{notify('وصل الجواب ديالك!');setGameAction('sent');await loadGame(game);}}
 async function finishGame(){if(!supabase||!game)return;setBusy(true);const {data,error}=await supabase.rpc(game.game_key==='impostor'?'finish_impostor_game':'finish_party_game',{p_session_id:game.id});setBusy(false);if(error)notify(prettyError(error));else{setGameResult(data);setGame({...game,status:'completed'});await loadGame({...game,status:'completed'});await loadProfile();await loadLeaderboard();await loadDailyMissions();}}
 async function exitRoom(){if(!supabase||!room)return;stopVoice();await supabase.rpc('leave_room',{p_room_id:room.id});setRoom(null);setGame(null);setTab('home');await loadRooms();}
 useEffect(()=>{const client=supabase;if(!room||!client)return;let active=true;const beat=async()=>{if(document.visibilityState==='hidden')return;const {data,error}=await client.rpc('heartbeat_room',{p_room_id:room.id});if(active&&!error&&!data){notify('الغرفة تسدات أو سالات الجلسة ديالك.');setRoom(null);setTab('rooms');await loadRooms();}};void beat();const timer=window.setInterval(beat,25000);const onVisible=()=>{if(document.visibilityState==='visible')void beat();};document.addEventListener('visibilitychange',onVisible);return()=>{active=false;window.clearInterval(timer);document.removeEventListener('visibilitychange',onVisible);};},[room?.id,loadRooms]);
 useEffect(()=>{if(!gameSecret?.deadline_at){setTimeLeft(10);return;}const update=()=>setTimeLeft(Math.max(0,Math.ceil((new Date(gameSecret.deadline_at).getTime()-Date.now())/1000)));update();const timerId=window.setInterval(update,200);return()=>window.clearInterval(timerId);},[gameSecret?.deadline_at]);
 
 useEffect(()=>{if(!game||game.status!=='active')return;const poll=window.setInterval(()=>void loadGame(game),2500);return()=>window.clearInterval(poll);},[game?.id,game?.status]);
 useEffect(()=>{if(tab!=='rooms')return;void loadRooms();const timer=window.setInterval(()=>void loadRooms(),20000);return()=>window.clearInterval(timer);},[tab,loadRooms]);
 useEffect(()=>{if(!supabase||!room)return;const ch=supabase.channel('dima-room-feed:'+room.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'chat_messages',filter:'room_id=eq.'+room.id},p=>{const m=p.new as any;setMessages(old=>old.some(x=>x.id===m.id)?old:[...old,m].slice(-60));}).on('postgres_changes',{event:'*',schema:'public',table:'game_sessions',filter:'room_id=eq.'+room.id},()=>void loadRoomData(room.id)).on('postgres_changes',{event:'*',schema:'public',table:'room_members',filter:'room_id=eq.'+room.id},()=>void loadRoomData(room.id)).subscribe();return()=>{void supabase?.removeChannel(ch);};},[room?.id]);

 function stopVoice(){
  if(voiceChannelRef.current&&supabase){void supabase.removeChannel(voiceChannelRef.current);voiceChannelRef.current=null;}
  peerConnectionsRef.current.forEach(pc=>pc.close());peerConnectionsRef.current.clear();
  remoteAudioRef.current.forEach(audio=>{audio.pause();audio.srcObject=null;});remoteAudioRef.current.clear();
  localStreamRef.current?.getTracks().forEach(track=>track.stop());localStreamRef.current=null;
  pendingIceRef.current.clear();setVoiceActive(false);setVoiceMuted(false);setVoiceStatus('الصوت مطفي');
 }
 async function startVoice(){
  if(!supabase||!room||!userId||voiceActive)return;
  if(!navigator.mediaDevices?.getUserMedia){setVoiceStatus('المتصفح ما كيدعمش المايك أو الصفحة ماشي HTTPS.');return;}
  try{
   setVoiceStatus('كنوجد الاتصال الصوتي...');
   let iceServers:RTCIceServer[]=[{urls:['stun:stun.cloudflare.com:3478','stun:stun.l.google.com:19302']}];
   try{const iceResponse=await fetch('https://dima-play-turn-api.m40065744.workers.dev/ice',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'}});if(!iceResponse.ok)throw new Error('TURN غير مهيأ');const iceData=await iceResponse.json();if(Array.isArray(iceData.iceServers)&&iceData.iceServers.length)iceServers=iceData.iceServers;}
   catch{setVoiceStatus('TURN مازال ما تهيّأش؛ غادي نجرب الاتصال المباشر.');}
   const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});
   localStreamRef.current=stream;
   const channel=supabase.channel('voice:'+room.id,{config:{private:true,presence:{key:userId},broadcast:{ack:true}}});
   voiceChannelRef.current=channel;
   const sendSignal=async(to:string,kind:string,data:any)=>{await channel.send({type:'broadcast',event:'signal',payload:{from:userId,to,kind,data}});};
   const makePeer=(peerId:string,initiator:boolean)=>{
    let pc=peerConnectionsRef.current.get(peerId);if(pc)return pc;
    pc=new RTCPeerConnection({iceServers});
    peerConnectionsRef.current.set(peerId,pc);
    stream.getTracks().forEach(track=>pc!.addTrack(track,stream));
    pc.onicecandidate=e=>{if(e.candidate)void sendSignal(peerId,'ice',e.candidate.toJSON());};
    pc.ontrack=e=>{let audio=remoteAudioRef.current.get(peerId);if(!audio){audio=new Audio();audio.autoplay=true;remoteAudioRef.current.set(peerId,audio);}audio.srcObject=e.streams[0];void audio.play().catch(()=>setVoiceStatus('ضغط على الصفحة باش تسمح بالصوت الوارد.'));};
    pc.onconnectionstatechange=()=>{if(pc&&(pc.connectionState==='failed'||pc.connectionState==='closed')){pc.close();peerConnectionsRef.current.delete(peerId);const audio=remoteAudioRef.current.get(peerId);if(audio){audio.pause();audio.srcObject=null;remoteAudioRef.current.delete(peerId);}}};
    if(initiator){void (async()=>{const offer=await pc!.createOffer();await pc!.setLocalDescription(offer);await sendSignal(peerId,'offer',pc!.localDescription);})().catch(()=>setVoiceStatus('فشل إنشاء اتصال صوتي مع لاعب.'));}
    return pc;
   };
   channel.on('broadcast',{event:'signal'},async({payload}:any)=>{
    if(!payload||payload.to!==userId||typeof payload.from!=='string'||payload.from===userId)return;
    try{
     let pc=peerConnectionsRef.current.get(payload.from);
     if(payload.kind==='offer'){pc=makePeer(payload.from,false);await pc.setRemoteDescription(payload.data);const queued=pendingIceRef.current.get(payload.from)||[];for(const candidate of queued)await pc.addIceCandidate(candidate);pendingIceRef.current.delete(payload.from);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await sendSignal(payload.from,'answer',pc.localDescription);}
     else if(payload.kind==='answer'&&pc){await pc.setRemoteDescription(payload.data);const queued=pendingIceRef.current.get(payload.from)||[];for(const candidate of queued)await pc.addIceCandidate(candidate);pendingIceRef.current.delete(payload.from);}
     else if(payload.kind==='ice'&&payload.data){if(pc?.remoteDescription)await pc.addIceCandidate(payload.data);else{const q=pendingIceRef.current.get(payload.from)||[];q.push(payload.data);pendingIceRef.current.set(payload.from,q);}}
    }catch{setVoiceStatus('وقع مشكل فالتفاوض الصوتي. عاود دخل للصوت.');}
   });
   channel.on('presence',{event:'sync'},()=>{
    const state=channel.presenceState() as Record<string,any[]>,ids=new Set<string>();
    Object.values(state).flat().forEach(meta=>{if(typeof meta?.user_id==='string'&&meta.user_id!==userId)ids.add(meta.user_id);});
    const peers=[...ids].sort().slice(0,5);
    for(const [id,pc] of peerConnectionsRef.current){if(!peers.includes(id)){pc.close();peerConnectionsRef.current.delete(id);const audio=remoteAudioRef.current.get(id);if(audio){audio.pause();audio.srcObject=null;remoteAudioRef.current.delete(id);}}}
    if(ids.size>5)setVoiceStatus('الغرفة الصوتية كتقبل 6 مشاركين كحد أقصى فهاد النسخة.');
    else setVoiceStatus('الصوت خدام — '+(ids.size+1)+' مشاركين');
    peers.forEach(id=>{if(userId<id)makePeer(id,true);});
   });
   channel.subscribe(async(status:string)=>{
    if(status==='SUBSCRIBED'){await channel.track({user_id:userId,joined_at:new Date().toISOString()});setVoiceActive(true);setVoiceStatus('الميك خدام. استعمل زر الكتم إلا بغيتي.');}
    else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){setVoiceStatus('تعذر الاتصال الصوتي. راجع صلاحيات Realtime.');stopVoice();}
   });
  }catch(e:any){setVoiceStatus(e?.name==='NotAllowedError'?'خاصك تسمح باستعمال المايك.':e?.message||'تعذر تشغيل المايك.');stopVoice();}
 }
 function toggleVoiceMute(){const next=!voiceMuted;localStreamRef.current?.getAudioTracks().forEach(track=>track.enabled=!next);setVoiceMuted(next);}
 useEffect(()=>()=>stopVoice(),[room?.id]);
